class Solution {
    public int reversePairs(int[] nums) {
        int[] temp = new int[nums.length];
        return sortAndCount(nums, 0, nums.length, temp);
    }

    private int sortAndCount(int[] nums, int left, int right, int[] temp) {
        if (right - left <= 1) return 0;
        int mid = left + (right - left) / 2;
        int count = sortAndCount(nums, left, mid, temp) + sortAndCount(nums, mid, right, temp);

        int scan = mid;
        for (int i = left; i < mid; i++) {
            while (scan < right && (long) nums[i] > 2L * nums[scan]) scan++;
            count += scan - mid;
        }

        int i = left;
        int j = mid;
        int k = left;
        while (i < mid && j < right) {
            if (nums[i] <= nums[j]) temp[k++] = nums[i++];
            else temp[k++] = nums[j++];
        }
        while (i < mid) temp[k++] = nums[i++];
        while (j < right) temp[k++] = nums[j++];
        for (i = left; i < right; i++) nums[i] = temp[i];
        return count;
    }
}

class Solution {
    public int reversePairs(int[] nums) {
        int[] temp = new int[nums.length];
        return count(nums, 0, nums.length, temp);
    }

    private int count(int[] nums, int left, int right, int[] temp) {
        if (right - left <= 1) return 0;
        int mid = left + (right - left) / 2;
        int answer = count(nums, left, mid, temp) + count(nums, mid, right, temp);
        for (int i = left; i < mid; i++) {
            int boundary = firstNotReverse(nums, mid, right, nums[i]);
            answer += boundary - mid;
        }
        merge(nums, left, mid, right, temp);
        return answer;
    }

    private int firstNotReverse(int[] nums, int left, int right, int value) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if ((long) value > 2L * nums[mid]) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    private void merge(int[] nums, int left, int mid, int right, int[] temp) {
        int i = left;
        int j = mid;
        int k = left;
        while (i < mid && j < right) {
            if (nums[i] <= nums[j]) temp[k++] = nums[i++];
            else temp[k++] = nums[j++];
        }
        while (i < mid) temp[k++] = nums[i++];
        while (j < right) temp[k++] = nums[j++];
        for (i = left; i < right; i++) nums[i] = temp[i];
    }
}

import java.util.*;

class Solution {
    private int[] bit;

    public int reversePairs(int[] nums) {
        TreeSet<Long> values = new TreeSet<>();
        for (int value : nums) {
            values.add((long) value);
            values.add(2L * value);
        }
        Map<Long, Integer> rank = new HashMap<>();
        int index = 1;
        for (long value : values) rank.put(value, index++);

        bit = new int[index + 1];
        int answer = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            answer += query(rank.get((long) nums[i]) - 1);
            add(rank.get(2L * nums[i]), 1);
        }
        return answer;
    }

    private void add(int index, int delta) {
        while (index < bit.length) {
            bit[index] += delta;
            index += index & -index;
        }
    }

    private int query(int index) {
        int sum = 0;
        while (index > 0) {
            sum += bit[index];
            index -= index & -index;
        }
        return sum;
    }
}

import java.util.*;

class Solution {
    private int[] tree;
    private int size;

    public int reversePairs(int[] nums) {
        TreeSet<Long> ordered = new TreeSet<>();
        for (int value : nums) {
            ordered.add((long) value);
            ordered.add(2L * value);
        }
        Map<Long, Integer> rank = new HashMap<>();
        int next = 1;
        for (long value : ordered) rank.put(value, next++);
        size = rank.size();
        tree = new int[size * 4 + 4];

        int answer = 0;
        for (int value : nums) {
            int doubledRank = rank.get(2L * value);
            answer += query(1, 1, size, doubledRank + 1, size);
            update(1, 1, size, rank.get((long) value));
        }
        return answer;
    }

    private void update(int node, int left, int right, int index) {
        if (left == right) {
            tree[node]++;
            return;
        }
        int mid = left + (right - left) / 2;
        if (index <= mid) update(node * 2, left, mid, index);
        else update(node * 2 + 1, mid + 1, right, index);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    private int query(int node, int left, int right, int ql, int qr) {
        if (ql > qr || right < ql || qr < left) return 0;
        if (ql <= left && right <= qr) return tree[node];
        int mid = left + (right - left) / 2;
        return query(node * 2, left, mid, ql, qr) + query(node * 2 + 1, mid + 1, right, ql, qr);
    }
}

class Solution {
    public int reversePairs(int[] nums) {
        Node root = null;
        int answer = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            answer += countDoubledLessThan(root, nums[i]);
            root = insert(root, nums[i]);
        }
        return answer;
    }

    private int countDoubledLessThan(Node node, long threshold) {
        if (node == null) return 0;
        if (2L * node.key < threshold) {
            return size(node.left) + node.count + countDoubledLessThan(node.right, threshold);
        }
        return countDoubledLessThan(node.left, threshold);
    }

    private Node insert(Node node, int key) {
        if (node == null) return new Node(key);
        if (key == node.key) {
            node.count++;
        } else if (key < node.key) {
            node.left = insert(node.left, key);
            if (node.left.priority < node.priority) node = rotateRight(node);
        } else {
            node.right = insert(node.right, key);
            if (node.right.priority < node.priority) node = rotateLeft(node);
        }
        update(node);
        return node;
    }

    private Node rotateRight(Node node) {
        Node top = node.left;
        node.left = top.right;
        top.right = node;
        update(node);
        update(top);
        return top;
    }

    private Node rotateLeft(Node node) {
        Node top = node.right;
        node.right = top.left;
        top.left = node;
        update(node);
        update(top);
        return top;
    }

    private int size(Node node) {
        return node == null ? 0 : node.size;
    }

    private void update(Node node) {
        node.size = node.count + size(node.left) + size(node.right);
    }

    private static int priority(int key) {
        int x = key;
        x ^= x >>> 16;
        x *= 0x7feb352d;
        x ^= x >>> 15;
        x *= 0x846ca68b;
        x ^= x >>> 16;
        return x & 0x7fffffff;
    }

    private static class Node {
        final int key;
        final int priority;
        int count = 1;
        int size = 1;
        Node left;
        Node right;

        Node(int key) {
            this.key = key;
            this.priority = priority(key);
        }
    }
}
